public static int binarySearch(String[]
list,String target)
{
  int mid = list.length/2;
  int front = 0;
  int back = list.length-1;
  while(back >= front)
  {
    if(list[mid].equals(target))
      return mid;
    if(target.compareTo(list[mid])>0)
      back = mid - 1;
    else
